package com.fasterxml.jackson.databind.ser;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import com.fasterxml.jackson.databind.ser.PropertyFilter;
import com.fasterxml.jackson.databind.ser.impl.MapSerializer;
import com.fasterxml.jackson.databind.ser.std.MapSerializer;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.ArgumentMatchers.isNull;
import static org.mockito.Mockito.*;

public class AnyGetterWriter_getAndFilter_TriageGen1Test {

    @Mock
    private JsonGenerator gen;

    @Mock
    private SerializerProvider provider;

    @Mock
    private PropertyFilter filter;

    @Mock
    private MapSerializer mapSerializer;

    @Mock
    private AnyGetterWriter._Accessor accessor;

    private AnyGetterWriter writer;

    // Inner class to mock the private/protected _accessor if necessary, 
    // but since we are testing the logic, we will use reflection or a subclass if the field is accessible.
    // Given the context, we assume we can inject the dependencies.

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        // We need to instantiate AnyGetterWriter. Since the constructor isn't provided in the prompt,
        // we assume a way to set the private fields _accessor and _mapSerializer via reflection.
        writer = new AnyGetterWriter();
        setField(writer, "_accessor", accessor);
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testGetAndFilter_ValueIsNull() throws Exception {
        Object bean = new Object();
        when(accessor.getValue(bean)).thenReturn(null);

        writer.getAndFilter(bean, gen, provider, filter);

        verify(accessor).getValue(bean);
        verifyNoInteractions(gen);
        verifyNoInteractions(provider);
        verifyNoInteractions(filter);
    }

    @Test(expected = JsonMappingException.class)
    public void testGetAndFilter_ValueIsNotMap() throws Exception {
        Object bean = new Object();
        String notAMap = "I am a string";
        when(accessor.getValue(bean)).thenReturn(notAMap);
        when(accessor.getName()).thenReturn("testGetter");

        try {
            writer.getAndFilter(bean, gen, provider, filter);
        } catch (JsonMappingException e) {
            // Verify error message contains expected content
            assert(e.getMessage().contains("not java.util.Map"));
            throw e;
        }
    }

    @Test
    public void testGetAndFilter_WithMapSerializer() throws Exception {
        Object bean = new Object();
        Map<String, Object> map = new HashMap<>();
        map.put("key", "value");

        setField(writer, "_mapSerializer", mapSerializer);
        when(accessor.getValue(bean)).thenReturn(map);

        writer.getAndFilter(bean, gen, provider, filter);

        verify(mapSerializer).serializeFilteredFields(eq(map), eq(gen), eq(provider), eq(filter), isNull());
    }

    @Test
    public void testGetAndFilter_WithoutMapSerializer_DoesNothing() throws Exception {
        // This covers the final "..." branch where _mapSerializer is null and value is a Map
        Object bean = new Object();
        Map<String, Object> map = new HashMap<>();

        setField(writer, "_mapSerializer", null);
        when(accessor.getValue(bean)).thenReturn(map);

        writer.getAndFilter(bean, gen, provider, filter);

        // If _mapSerializer is null, the method reaches the end of the logic provided
        verify(accessor).getValue(bean);
        verifyNoInteractions(mapSerializer);
    }

    /**
     * Mocking the internal Accessor class structure based on the usage in the method.
     */
    private static class AnyGetterWriter extends com.fasterxml.jackson.databind.ser.AnyGetterWriter {
        // This is a dummy implementation to allow field injection in tests 
        // if the real class is not easily instantiable.
        public AnyGetterWriter() {
            super(null, null, null, null); 
        }
    }
}
